import json,collections,statistics,zipfile,hashlib
from pathlib import Path
from priority_cell_analysis import rows,sheets,sign,number
R=Path(__file__).parent;P=R/'priority-now'
a=json.loads((P/'cell_analysis.json').read_text());sel=json.loads((P/'priority_selection.json').read_text());rules=json.loads((P/'PAPER_STRATEGIES.json').read_text())
C=a['counts'];D=a['distributions'];days=list(C)
def metric(day,key):return next(x for x in D if x['day']==day and x['metric']==key)
def total(key):return sum(c.get(key,0) for c in C.values())
def listcount(key):return ' / '.join(str(C[d].get(key,0)) for d in days)
def pct(n,d):return f'{100*n/d:.1f}%' if d else 'n/a'

# Additional feedback diagnostics read the saved cells; full depth and touch stay separate.
extra=collections.defaultdict(collections.Counter);dis=collections.defaultdict(list)
with zipfile.ZipFile(P/'Frankie_four_day_priority_ten.xlsx') as z:
 m=sheets(z)
 for n,r in rows(z,m['P02 Flow depth and refill']):
  day=r['Trading date'];f=sign(r.get('f5'));depth=sign(r.get('dsg'));touch=sign(r.get('touch_imb'));prior=sign(r.get('prior_tk_20s'))
  if depth is not None and touch is not None:extra[day]['full_depth_vs_touch_'+('opposed' if depth*touch<0 else 'neutral' if depth*touch==0 else 'aligned')]+=1
  relation='missing' if f is None or prior is None else 'neutral' if f*prior==0 else 'aligned' if f==prior else 'opposed'
  extra[day]['prior_price_vs_flow_'+relation]+=1
  v=number(r.get('tk_20s'))
  if v is not None and f not in (None,0):dis[(day,relation)].append(v*f)
feedback={'counts':dict(extra),'future_20s_ticks_by_prior_price_flow_relation':[{ 'day':d,'relation':k,'n':len(v),'mean':statistics.mean(v),'positive':sum(t>0 for t in v),'negative':sum(t<0 for t in v),'flat':sum(t==0 for t in v)} for (d,k),v in dis.items()], 'limit':'Prior 20-second price state -> current flow/depth -> later 20-second price diagnostic; retrospective family selection and same-message mechanics prevent causal interpretation.'}
(P/'price_feedback_cells.json').write_text(json.dumps(feedback,indent=2))

fcount=total('flow_age_only_changes');changes=total('flow_ratio_changes');rests=total('rest_events');surv=total('rest_eligible_25ms');rec=total('P09_rows')
findings=[
 ['P01','Fresh versus expiring flow',f'{fcount:,}/{changes:,} ratio changes ({pct(fcount,changes)}) had no fresh classified buy/sell volume. Four final seconds have no completion clock.','Arm only on newly observed aggression. Use completed-known-by clocks; P01 is in Priority_native_flow.xlsx.'],
 ['P02','Flow, full depth and refill',f"Five-second flow/full-depth: {total('family_flow_depth_aligned'):,} aligned, {total('family_flow_depth_opposed'):,} opposed, {total('family_flow_depth_neutral'):,} neutral, {total('family_flow_depth_missing'):,} missing. Full depth is not touch imbalance.",'Keep full-depth, near-depth and touch signs distinct; no missing-to-zero conversion.'],
 ['P03','Agreement and disagreement','Aligned 60s oriented mean ticks by date: '+', '.join(f"{metric(d,'candidate_aligned_flow_oriented_60s_ticks')['mean']:.3f}" for d in days)+'. Opposed: '+', '.join(f"{metric(d,'candidate_opposed_flow_oriented_60s_ticks')['mean']:.3f}" for d in days)+'.','Agreement does not dominate on every date. R1 is an untested composite hypothesis, not an established edge.'],
 ['P04','Order identity and lifecycle',f'{rests:,} aggression-to-rest episodes; median duration by date '+', '.join(f"{metric(d,'rest_duration_ms')['median']:.2f}ms" for d in days)+'. Remaining P04 rows are actions.','An order-ID sequence is not trader intent. Final fate cannot enter a trigger.'],
 ['P05','Resting state known by decision',f'{surv:,}/{rests:,} episodes ({pct(surv,rests)}) remain eligible at scheduled +25ms. No future-action cutoff violations in these rows.','Scheduled survival is not latency or our fill probability. Require current surviving state and measured arrival.'],
 ['P06','Matched controls and gaps',f"Matched case flags: {total('prebirth_case_matched_1'):,}; unmatched: {total('prebirth_case_matched_0'):,}. Complete pair-feature and case records retained.",'Future-excluded controls are retrospective. Do not use cohort/control membership online or count pair-feature rows as independent trades.'],
 ['P07','One-lot order origin',f"{total('P07_rows'):,} onsets: {total('one_lot_outcome_RETREATED'):,} retreated, {total('one_lot_outcome_SIZE_RECOVERED_AT_SAME_PRICE'):,} recovered size, {total('one_lot_outcome_IMPROVED'):,} improved. Repeated order onsets remain visible.",'Thin touch alone is not an entry. Preserve order age, onset history and contrary fates.'],
 ['P08','Event order and lean',f"{total('first_event_aggression_first'):,} aggression-first, {total('first_event_price_first'):,} price-first, {total('first_event_same_bin'):,} same-bin, {total('first_event_missing_or_censored'):,} censored/missing among {total('first_event_candidates'):,} retrospective tapes.",'Price can precede measured aggression. Birth alignment and bin order do not establish warning lead or causality.'],
 ['P09','Recognition boundary',f"Median birth-to-recognition elapsed time by date: "+', '.join(f"{metric(d,'recognition_elapsed_s')['median']:.2f}s" for d in days)+f". Undefined flow at emission: {total('recognition_flow_undefined_at_emission'):,}/{rec:,}.",'Recognition is late relative to retrospective birth; no verified 0.5s warning. Later price response is a different measure.'],
 ['P10','Price, flow and book context',f"{total('context_dipole_state_both_empty'):,}/{total('P10_rows'):,} contexts have both flow halves empty. No future quote/flow-known-by violations in checked clocks.",'Observe price feedback and empty states; availability alone does not prove predictive value.']
]
summary=[{'name':'Priority findings','headers':['Priority','Focus','Cell-derived finding','Consequence for paper rules'],'rows':findings,'widths':[10,28,76,64]}]
