for k in ['clock_and_input_contract','fill_and_exit_model','portfolio_and_session','observation_only']:
 paperrows += [[k.replace('_',' ').capitalize()+f' {i}',v] for i,v in enumerate(rules[k],1)]
for s in rules['strategies']:
 paperrows += [[s['id']+' '+k,s[k]] for k in ['name','trigger','confirmation','entry','invalidation','interpretation']]
