summary.append({'name':'Paper rules v1','headers':['Rule or setting','Frozen specification — prospective paper only'],'rows':paperrows,'widths':[36,145]})
metricrows=[[d['day'],d['metric'],d['n'],d['mean'],d['median'],d['minimum'],d['maximum'],d['positive'],d['negative'],d['flat'],'All finite observations in named population; not independent trade PnL'] for d in D]
